_LOCK = threading.RLock()
_MEMO: dict[str, object] = {}


def _memo(key, build):
    with _LOCK:
        if key not in _MEMO:
            try:
                _MEMO[key] = build()
            except Exception:  # a broken submission must never abort grading
                _MEMO[key] = None
        return _MEMO[key]


# ------------------------------------------------------------- ground truth --
def _blob(text: str) -> dict:
    return json.loads(zlib.decompress(base64.b64decode(text)).decode("utf-8"))


def _truth() -> dict:
    return _memo("truth", lambda: _blob(_TRUTH_BLOB))


def _variant() -> dict:
    return _memo("variant", lambda: _blob(_VARIANT_BLOB))


def _truth_text(phase: str, name: str) -> str:
    return _truth()[phase][name]


def _rows(text):
    """Parse contract CSV text into (header, list of row dicts); None on bad shape."""
    if not isinstance(text, str) or not text.endswith("\n"):
        return None
    lines = text[:-1].split("\n")
    head = lines[0].split(",")
    out = []
    for ln in lines[1:]:
        cells = ln.split(",")
        if len(cells) != len(head):
            return None
        out.append(dict(zip(head, cells)))
    return head, out


def _keyed(text, key_cols, val_cols):
    parsed = _rows(text)
    if parsed is None:
        return None
    head, rows = parsed
    if any(c not in head for c in list(key_cols) + list(val_cols)):
        return None
    out = {}
    for r in rows:
        k = tuple(r[c] for c in key_cols)
        if k in out:
            return None
        out[k] = tuple(r[c] for c in val_cols)
    return out


def _same_fields(candidate_text, truth_text, key_cols, val_cols, exact_keys=False) -> bool:
    got = _keyed(candidate_text, key_cols, val_cols)
    want = _keyed(truth_text, key_cols, val_cols)
    if got is None or want is None or not want:
        return False
    if exact_keys:
        return set(got) == set(want) and all(got[k] == v for k, v in want.items())
    shared = [k for k in want if k in got]
    if len(shared) < MIN_COVER * len(want):
        return False
    return all(got[k] == want[k] for k in shared)


def _ordered(text, cols):
    parsed = _rows(text)
    if parsed is None or any(c not in parsed[0] for c in cols):
        return None
    return [tuple(r[c] for c in cols) for r in parsed[1]]


def _strict_equal(a, b) -> bool:
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(_strict_equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(_strict_equal(x, y) for x, y in zip(a, b))
    return a == b


def _json(text):
    try:
        return json.loads(text)
    except (TypeError, ValueError):
        return None


def _declared(phase: str, name: str):
    try:
        return (OUT / phase / name).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


# ------------------------------------------------------ running the program --
def _staged_program():
    """A verifier-owned copy of build.py.

    The unprivileged run executes this staged copy (mode 0755), so the 0600 mode
    an agent editor leaves on build.py does not matter, and graded content is
    unchanged.
    """
    def build():
        if not PROGRAM.is_file():
            return None
        where = _scratch() / "prog"
        where.mkdir()
        target = where / "build.py"
        shutil.copyfile(PROGRAM, target)
        target.chmod(0o755)
        where.chmod(0o755)
        return target
    return _memo("staged-program", build)


def _untrusted_command(program: Path, args: list[str]) -> list[str]:
    command = [sys.executable, "-I", str(program), *args]
    if os.name == "posix" and os.geteuid() == 0:
        try:
            # Root keeps reading the declared files; the dropped uid cannot, so a
            # program cannot copy them into its output instead of computing.
            OUT.chmod(0o700)
        except OSError:
            pass
        return [*_SETPRIV, *command]
    return command


def _kill_group(proc) -> None:
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except (OSError, ProcessLookupError):
        pass


def _run_build(args, hash_seed="1", timeout=STAGE_TIMEOUT):
    """Run the staged build.py unprivileged; returns (returncode, stdout, stderr) or None."""
    program = _staged_program()
    if program is None:
        return None
    cmd = _untrusted_command(program, [str(a) for a in args])
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8",
           "HOME": "/tmp", "PYTHONHASHSEED": hash_seed}
    proc = subprocess.Popen(cmd, cwd="/tmp", stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE, env=env, start_new_session=True)
    try:
        out, err = proc.communicate(timeout=timeout)
        code = proc.returncode
    except subprocess.TimeoutExpired:
        _kill_group(proc)
        out, err = proc.communicate()
        code = None
    finally:
        _kill_group(proc)
    return code, out.decode("utf-8", "replace"), err.decode("utf-8", "replace")


def _scratch() -> Path:
    def build():
        root = Path(tempfile.mkdtemp(prefix="vrf-"))
        root.chmod(0o755)
        return root
    return _memo("scratch", build)


def _open_dir(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    path.chmod(0o1777)
    return path


def _expose(paths, on: bool) -> None:
    """Staged inputs are readable only while the run that uses them is going."""
    for p in paths:
        try:
            Path(p).chmod(0o755 if on else 0o700)
        except OSError:
            pass


def _share_tree(path: Path) -> None:
    for p in [path, *path.rglob("*")]:
        p.chmod(0o755 if p.is_dir() else 0o644)


def _corpus_base() -> Path:
    def build():
        base = _scratch() / "corpus-base"
        for rel, blob in _SHIPPED_DATA.items():
            target = base / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(zlib.decompress(base64.b64decode(blob)))
        _share_tree(base)
        return base
    return _memo("corpus-base", build)


def _perturb_corpus(path: Path) -> None:
    """Halve every trial's out_bytes, which changes every compression ratio."""
    bench = path / "codec_bench.csv"
    lines = bench.read_text(encoding="utf-8").split("\n")
    head = lines[0].split(",")
    col = head.index("out_bytes")
    out = [lines[0]]
    changed = 0
    for ln in lines[1:]:
        cells = ln.split(",")
        if len(cells) == len(head) and cells[col].isdigit():
            cells[col] = str(max(1, int(cells[col]) // 2))
            changed += 1
        out.append(",".join(cells))
    if changed == 0:
        raise RuntimeError("benchmark perturbation changed nothing")
    bench.write_text("\n".join(out), encoding="utf-8")


def _stage_corpus(where: Path, perturbed: bool) -> Path:
    if where.exists():
        shutil.rmtree(where)
    shutil.copytree(_corpus_base(), where)
    if perturbed:
        _perturb_corpus(where)
    _share_tree(where)
    where.chmod(0o700)
    return where


def _stage_files(where: Path, files: dict) -> Path:
    if where.exists():
        shutil.rmtree(where)
    where.mkdir(parents=True)
    for name, text in files.items():
        (where / name).write_text(text, encoding="utf-8")
    _share_tree(where)
    where.chmod(0o700)
    return where


def _collect(out_dir: Path, names) -> dict:
    found = {}
    for n in names:
        try:
            found[n] = (out_dir / n).read_bytes()
        except OSError:
            found[n] = None
    return found


def _plant_dir() -> Path:
    return Path("/app") / "data"


class _Planted:
    """Temporarily place a corpus at the agent's input mount inside the verifier."""

    def __init__(self, perturbed: bool):
        self.perturbed = perturbed
        self.made = False

    def __enter__(self):
        target = _plant_dir()
        if target.exists():
            raise RuntimeError("input mount unexpectedly present in the verifier")
        _stage_corpus(target, self.perturbed)
        target.chmod(0o755)
        self.made = True
        return target

    def __exit__(self, *exc):
        if self.made and _plant_dir().exists():
            shutil.rmtree(_plant_dir(), ignore_errors=True)
        return False


def _ensure_unplanted() -> bool:
    return not _plant_dir().exists()


def _phase_run(key, phase, inputs, out_name, names, seed="1", plant=None):
    """Run one phase into a fresh output directory; returns dict or None."""
    limit = RUN_TIMEOUT if phase == "phase1" else STAGE_TIMEOUT

    def build():
        parent = _open_dir(_scratch() / key)
        out_dir = parent / out_name
        _expose(inputs, True)
        try:
            if plant is None:
                if not _ensure_unplanted():
                    return None
                res = _run_build([phase, *inputs, out_dir], seed, limit)
            else:
                with _Planted(plant):
                    res = _run_build([phase, *inputs, out_dir], seed, limit)
        finally:
            _expose(inputs, False)
        if res is None:
            return None
        return {"code": res[0], "stderr": res[2], "files": _collect(out_dir, names), "out": out_dir}
    return _memo(key, build)


def _sig(run):
    if run is None:
        return None
    return (run["code"], tuple(sorted((k, v) for k, v in run["files"].items())))


def _ok(run) -> bool:
    return run is not None and run["code"] == 0 and all(v is not None for v in run["files"].values())


def _text(run, name):
    if not _ok(run):
        return None
    try:
        return run["files"][name].decode("utf-8")
    except UnicodeDecodeError:
        return None


def _truth_p1_dir(key):
    return _memo(f"stage-{key}", lambda: _stage_files(_scratch() / key / "up1", _truth()["p1"]))


def _truth_p2_dir(key):
    return _memo(f"stage2-{key}", lambda: _stage_files(_scratch() / key / "up2", _truth()["p2"]))


