def _bump_column(files, name, col, delta):
    lines = files[name].rstrip("\n").split("\n")
    head = lines[0].split(",")
    j = head.index(col)
    out = [lines[0]]
    for ln in lines[1:]:
        cells = ln.split(",")
        cells[j] = str(int(cells[j]) + delta)
        out.append(",".join(cells))
    files[name] = "\n".join(out) + "\n"
    return files


def _perturbed_p1():
    return _bump_column(dict(_truth()["p1"]), "nodes.csv", "usable_bytes", 10 * (1 << 30))


def _perturbed_p2():
    return _bump_column(dict(_truth()["p2"]), "shield_alloc.csv", "granted_kib", 1000000)


