def _declared_dir(phase, names):
    files = {}
    for n in names:
        t = _declared(phase, n)
        if t is None:
            return None
        files[n] = t
    return files


def run_p2_declared():
    def stage():
        files = _declared_dir("p1", P1_FILES)
        return None if files is None else _stage_files(_scratch() / "d2" / "in1", files)
    up = _memo("stage-d2", stage)
    if up is None:
        return None
    return _phase_run("d2-run", "phase2", [up], "r2", P2_FILES, "1")


def run_p3_declared():
    def stage():
        f1 = _declared_dir("p1", P1_FILES)
        f2 = _declared_dir("p2", P2_FILES)
        if f1 is None or f2 is None:
            return None
        return (_stage_files(_scratch() / "d3" / "in1", f1), _stage_files(_scratch() / "d3" / "in2", f2))
    ups = _memo("stage-d3", stage)
    if ups is None:
        return None
    return _phase_run("d3-run", "phase3", list(ups), "r3", P3_FILES, "1")


def _tree_state(root: Path, skip: Path) -> dict:
    state = {}
    for p in sorted(root.rglob("*")):
        if p == skip or skip in p.parents:
            continue
        if p.is_file():
            state[str(p)] = hashlib.sha256(p.read_bytes()).hexdigest()
        else:
            state[str(p)] = "dir"
    return state


def run_scope_probe():
    """Phase 2 on the true phase 1 files; records everything outside the output."""
    def build():
        parent = _open_dir(_scratch() / "sc")
        up = _stage_files(parent / "up1", _truth()["p1"])
        out_dir = parent / "only-here"
        _expose([up], True)
        before = _tree_state(parent, out_dir)
        if not _ensure_unplanted():
            return None
        try:
            res = _run_build(["phase2", up, out_dir], "1")
        finally:
            after = _tree_state(parent, out_dir)
            _expose([up], False)
        return {"code": None if res is None else res[0], "before": before, "after": after}
    return _memo("scope-probe", build)


def run_usage_probe():
    """Missing/unknown subcommand, then each phase with one argument too few or too many.

    Every arity probe hands valid upstream directories, so the argument count is
    the only fault and no precedence between exit 2 and exit 3 is assumed.
    """
    def build():
        parent = _open_dir(_scratch() / "ar")
        src = _stage_corpus(parent / "src", False)
        up1, up2 = _truth_p1_dir("ar"), _truth_p2_dir("ar")
        cases = {
            "no-subcommand": ([], []),
            "unknown-subcommand": (["phase9", "/tmp", "/tmp"], []),
            "phase1-short": (["phase1", src], []),
            "phase2-extra": (["phase2", up1, parent / "p2x-out", parent / "p2x-extra"],
                             [parent / "p2x-out", parent / "p2x-extra"]),
            "phase3-short": (["phase3", up1, up2], []),
            "phase3-extra": (["phase3", up1, up2, parent / "p3x-out", parent / "p3x-extra"],
                             [parent / "p3x-out", parent / "p3x-extra"]),
        }
        staged = [src, up1, up2]
        found = {}
        _expose(staged, True)
        try:
            for name, (args, outs) in cases.items():
                res = _run_build(args, "1")
                left = sorted(p.name for o in outs if o.is_dir() for p in o.iterdir())
                found[name] = {"res": res, "left": left}
        finally:
            _expose(staged, False)
        return found
    return _memo("usage-probe", build)


def _upstream_case(parent, name, phase, staged, unreadable=None):
    out_dir = parent / f"{name}-out"
    if unreadable is not None:
        unreadable.chmod(0o000)
    _expose(staged, True)
    try:
        res = _run_build([phase, *staged, out_dir], "1")
    finally:
        _expose(staged, False)
        if unreadable is not None:
            unreadable.chmod(0o644)
    left = sorted(p.name for p in out_dir.iterdir()) if out_dir.is_dir() else []
    return {"res": res, "left": left}


def run_upstream_probe():
    """Each upstream fault the instruction names, one per run, each into a fresh output dir."""
    def build():
        parent = _open_dir(_scratch() / "nx")
        t1, t2 = _truth()["p1"], _truth()["p2"]
        man = _json(t2["manifest.json"])
        man["phase"] = 3
        t2_wrong_phase = dict(t2)
        t2_wrong_phase["manifest.json"] = json.dumps(man, indent=2, sort_keys=True) + "\n"
        unread = _stage_files(parent / "ur1", t1)
        return {
            "missing-dir": _upstream_case(parent, "missing", "phase2", [parent / "no-such-upstream"]),
            "lacks-file": _upstream_case(parent, "lacks", "phase2",
                                         [_stage_files(parent / "lk1", {n: t for n, t in t1.items() if n != "pops.json"})]),
            "unreadable-file": _upstream_case(parent, "unread", "phase2", [unread], unreadable=unread / "nodes.csv"),
            # altered phase 1 beside the true phase 2: the manifest's inputs no longer bind it
            "manifest-mismatch": _upstream_case(parent, "mismatch", "phase3",
                                                [_stage_files(parent / "mm1", _perturbed_p1()),
                                                 _stage_files(parent / "mm2", t2)]),
            # true files, but the phase 2 manifest does not declare phase 2
            "manifest-wrong-phase": _upstream_case(parent, "wphase", "phase3",
                                                   [_stage_files(parent / "wp1", t1),
                                                    _stage_files(parent / "wp2", t2_wrong_phase)]),
        }
    return _memo("upstream-probe", build)


def run_overwrite_probe():
    def build():
        parent = _open_dir(_scratch() / "ow")
        up = _stage_files(parent / "up1", _truth()["p1"])
        out_dir = _open_dir(parent / "full")
        for n in P2_FILES:
            (out_dir / n).write_text(GARBAGE + "\n", encoding="utf-8")
        (out_dir / "operator-notes.txt").write_text("keep me\n", encoding="utf-8")
        _share_tree(out_dir)
        out_dir.chmod(0o777)
        for p in out_dir.iterdir():
            p.chmod(0o666)
        _expose([up], True)
        try:
            res = _run_build(["phase2", up, out_dir], "1")
        finally:
            _expose([up], False)
        return {"res": res, "files": _collect(out_dir, P2_FILES), "names": sorted(p.name for p in out_dir.iterdir())}
    return _memo("overwrite-probe", build)


# ======================================================================
# Shape checks
# ======================================================================
@unscored(description="All nineteen declared artifacts exist under /app/out as non-empty regular files")
def artifacts_present(workspace: Path) -> bool:
    try:
        paths = [OUT / "build.py"] + [OUT / "p1" / n for n in P1_FILES] + \
                [OUT / "p2" / n for n in P2_FILES] + [OUT / "p3" / n for n in P3_FILES]
        return all(p.is_file() and p.stat().st_size > 0 for p in paths)
    except OSError:
        return False


@unscored(description="Every declared CSV and JSON artifact follows the contract file format with LF endings and a final newline")
def artifact_file_format(workspace: Path) -> bool:
    try:
        for phase, names in (("p1", P1_FILES), ("p2", P2_FILES), ("p3", P3_FILES)):
            for n in names:
                raw = (OUT / phase / n).read_bytes()
                if b"\r" in raw or not raw.endswith(b"\n") or raw.startswith(b"\xef\xbb\xbf"):
                    return False
                text = raw.decode("utf-8")
                if n.endswith(".csv") and text.split("\n", 1)[0] != HEADERS[n]:
                    return False
                if n.endswith(".json"):
                    obj = json.loads(text)
                    if text != json.dumps(obj, indent=2, sort_keys=True) + "\n":
                        return False
        return True
    except (OSError, UnicodeDecodeError, ValueError):
        return False


# ======================================================================
# Phase 1, declared artifacts against the ground truth
# ======================================================================
def _p1(name, keys, cols, exact_keys=False) -> bool:
    try:
        return _same_fields(_declared("p1", name), _truth_text("p1", name), keys, cols, exact_keys)
    except Exception:
        return False


NODE = ["node_id"]
PAIR = ["node_id", "property"]


def _p1_for_pop(name, cols, pop) -> bool:
    try:
        _, nodes = _rows(_truth_text("p1", "nodes.csv"))
        node_ids = {row["node_id"] for row in nodes if row["pop"] == pop}
        _, got_rows = _rows(_declared("p1", name))
        _, want_rows = _rows(_truth_text("p1", name))
        got = [row for row in got_rows if row.get("node_id") in node_ids]
        want = [row for row in want_rows if row.get("node_id") in node_ids]
        got_map = {(row["node_id"], row["property"]): tuple(row[col] for col in cols) for row in got}
        want_map = {(row["node_id"], row["property"]): tuple(row[col] for col in cols) for row in want}
        common = got_map.keys() & want_map.keys()
        return (bool(want_map) and len(common) >= len(want_map) * MIN_COVER
                and all(got_map[key] == want_map[key] for key in common))
    except Exception:
        return False


def _same_order(name, keys) -> bool:
    got = _ordered(_declared("p1", name), keys)
    return got is not None and got == _ordered(_truth_text("p1", name), keys)


