@unscored(description="p1 pending.json holds the cut and exactly the pending amendment ids in contract order")
def p1_pending_ids_and_order(workspace: Path) -> bool:
    try:
        got = _json(_declared("p1", "pending.json"))
        want = _json(_truth_text("p1", "pending.json"))
        if not isinstance(got, dict) or not isinstance(got.get("amendments"), list):
            return False
        return (got.get("freeze_utc") == want["freeze_utc"]
                and [a.get("id") if isinstance(a, dict) else None for a in got["amendments"]]
                == [a["id"] for a in want["amendments"]])
    except Exception:
        return False


@unscored(description="p1 pending.json gives each pending amendment its target, field, typed value and effective instant")
def p1_pending_details(workspace: Path) -> bool:
    try:
        got = _json(_declared("p1", "pending.json"))
        want = _json(_truth_text("p1", "pending.json"))
        got_by = {a.get("id"): a for a in got["amendments"] if isinstance(a, dict)}
        return all(a["id"] in got_by and _strict_equal(got_by[a["id"]], a) for a in want["amendments"])
    except Exception:
        return False


def _pops_fields(fields):
    try:
        got = _json(_declared("p1", "pops.json"))
        want = _json(_truth_text("p1", "pops.json"))
        got_by = {s.get("pop"): s for s in got["pops"] if isinstance(s, dict)}
        if [s.get("pop") if isinstance(s, dict) else None for s in got["pops"]] != [s["pop"] for s in want["pops"]]:
            return False
        return all(all(_strict_equal(got_by[s["pop"]].get(f), s[f]) for f in fields) for s in want["pops"])
    except Exception:
        return False


