def phase1_rerun_matches_declared(workspace: Path) -> bool:
    try:
        run = run_p1_a()
        if not _ok(run):
            return False
        return all((OUT / "p1" / n).read_bytes() == run["files"][n] for n in P1_FILES)
    except Exception:
        return False


# ======================================================================
# Phase 2 and phase 3, program run on the true upstream and on the variant
# ======================================================================
def _graded_runs(phase):
    if phase == "p2":
        yield run_p2_truth(), _truth()["p2"]
        yield run_p2_variant(), _variant()["p2"]
    else:
        yield run_p3_truth(), _truth()["p3"]
        yield run_p3_variant(), _variant()["p3"]


def _fields_match(phase, name, keys, cols) -> bool:
    try:
        return all(_same_fields(_text(run, name), want[name], keys, cols, exact_keys=True)
                   for run, want in _graded_runs(phase))
    except Exception:
        return False


def _rows_match(phase, name, cols) -> bool:
    try:
        for run, want in _graded_runs(phase):
            got = _ordered(_text(run, name), cols)
            if got is None or got != _ordered(want[name], cols):
                return False
        return True
    except Exception:
        return False


def _manifest_match(phase, keys) -> bool:
    try:
        for run, want_files in _graded_runs(phase):
            got = _json(_text(run, "manifest.json"))
            want = _json(want_files["manifest.json"])
            if not isinstance(got, dict) or not all(_strict_equal(got.get(k), want[k]) for k in keys):
                return False
        return True
    except Exception:
        return False


