@unscored(description="declared p2 manifest.json records the SHA-256 of each declared phase 1 file")
def phase2_digests_bind_phase1(workspace: Path) -> bool:
    try:
        man = _json(_declared("p2", "manifest.json"))
        want = {n: hashlib.sha256((OUT / "p1" / n).read_bytes()).hexdigest() for n in P1_FILES}
        return isinstance(man, dict) and man.get("inputs") == want
    except Exception:
        return False


@unscored(description="build.py rewrites all six phase 2 files when the output directory already holds stale copies")
def phase2_overwrites_stale_outputs(workspace: Path) -> bool:
    try:
        probe = run_overwrite_probe()
        if probe is None or probe["res"] is None or probe["res"][0] != 0:
            return False
        for n in P2_FILES:
            raw = probe["files"][n]
            if raw is None or GARBAGE.encode() in raw:
                return False
            text = raw.decode("utf-8")
            if n.endswith(".csv") and text.split("\n", 1)[0] != HEADERS[n]:
                return False
            if n.endswith(".json") and _json(text) is None:
                return False
        return True
    except Exception:
        return False


@unscored(description="build.py exits 2 with an error usage line for a missing or unknown subcommand or a wrong number of arguments")
def usage_errors_exit_two(workspace: Path) -> bool:
    try:
        probe = run_usage_probe()
        if probe is None:
            return False
        return all(c["res"] is not None and c["res"][0] == 2
                   and c["res"][2].lstrip("\n").startswith("error: usage: ") for c in probe.values())
    except Exception:
        return False


